import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FaCalendarAlt, FaUsers, FaTheaterMasks, FaDownload } from 'react-icons/fa';
import axios from 'axios';
import persianDate from '../utils/persianDate';
import './Home.css';

interface Announcement {
  id: number;
  title: string;
  description: string;
  date: string;
  time: string;
  venue: string;
  price?: string;
  program_title?: string;
  created_at: string;
}

const Home: React.FC = () => {
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState('');
  const [currentTime, setCurrentTime] = useState('');

  useEffect(() => {
    setCurrentDate(persianDate.getCurrentDateTime());
    setCurrentTime(new Date().toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    const timeInterval = setInterval(() => {
      setCurrentTime(new Date().toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    }, 1000);
    fetchAnnouncements();
    return () => clearInterval(timeInterval);
  }, []);

  const fetchAnnouncements = async () => {
    try {
      const response = await axios.get('/api/announcements', {
        params: { limit: 6, status: 'published' }
      });
      setAnnouncements(response.data);
    } catch (error) {
      console.error('Error fetching announcements:', error);
    } finally {
      setLoading(false);
    }
  };

  const getTodayAnnouncements = () => {
    const todayGregorian = new Date().toISOString().split('T')[0];
    return announcements.filter(ann => ann.date === todayGregorian);
  };

  const getRecentAnnouncements = () => {
    return announcements.slice(0, 3);
  };

  if (loading) {
    return (
      <div className="home-container">
        <div className="loading">در حال بارگذاری...</div>
      </div>
    );
  }

  const todayAnnouncements = getTodayAnnouncements();
  const recentAnnouncements = getRecentAnnouncements();

  return (
    <div className="home-container">
      {/* Hero Section */}
      <section className="hero-section">
        <div className="hero-content">
          <h1 className="hero-title">سامانه مدیریت یکپارچه و هوشمند صدور آفیش رسا</h1>
          <p className="hero-description">
            یک پلتفرم یکپارچه برای مدیریت هوشمند صدور آفیش – سامانه رسا
          </p>
          <div className="hero-stats">
            <div className="stat-item">
              <FaCalendarAlt className="stat-icon" />
              <div className="stat-info">
                <div className="stat-number">{announcements.length}</div>
        <div className="stat-label">آفیش ثبت شده</div>
              </div>
            </div>
            <div className="stat-item">
              <FaUsers className="stat-icon" />
              <div className="stat-info">
                <div className="stat-number">{todayAnnouncements.length}</div>
                <div className="stat-label">برنامه امروز</div>
              </div>
            </div>
          </div>
          <div className="hero-actions">
            <Link to="/display" className="btn btn-primary">
              <FaTheaterMasks />
              مشاهده برنامه‌ها
            </Link>
            <Link to="/dashboard" className="btn btn-secondary">
              داشبورد مدیریت
            </Link>
          </div>
        </div>
      </section>

      {/* Current Date */}
      <section className="date-section">
        <div className="date-display">
          <div className="date-item">
            <span className="date-label">تاریخ امروز:</span>
            <span className="date-value">{currentDate}</span>
          </div>
          <div className="date-item">
            <span className="date-label">روز هفته:</span>
            <span className="date-value">{persianDate.getDayName()}</span>
          </div>
          <div className="date-item">
            <span className="date-label">ساعت اکنون:</span>
            <span className="date-value">{currentTime}</span>
          </div>
        </div>
      </section>

      {/* Today's Announcements */}
      {todayAnnouncements.length > 0 && (
        <section className="announcements-section">
          <h2 className="section-title">برنامه‌های امروز</h2>
          <div className="announcements-grid">
            {todayAnnouncements.map(announcement => (
              <div key={announcement.id} className="announcement-card today">
                <div className="card-header">
                  <h3 className="card-title">{announcement.title}</h3>
                  <span className="time-badge">{announcement.time}</span>
                </div>
                <p className="card-description">{announcement.description}</p>
                <div className="card-details">
                  <div className="detail-item">
                    <span className="detail-label">مکان:</span>
                    <span className="detail-value">{announcement.venue}</span>
                  </div>
                  {announcement.price && (
                    <div className="detail-item">
                      <span className="detail-label">قیمت:</span>
                      <span className="detail-value">{announcement.price}</span>
                    </div>
                  )}
                </div>
                <div className="card-actions">
                  <Link to={`/poster/${announcement.id}`} className="btn btn-outline">
                    <FaDownload />
                    دانلود پوستر
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Recent Announcements */}
      {recentAnnouncements.length > 0 && (
        <section className="announcements-section">
      <h2 className="section-title">آخرین آفیش‌ها</h2>
          <div className="announcements-grid">
            {recentAnnouncements.map(announcement => (
              <div key={announcement.id} className="announcement-card">
                <div className="card-header">
                  <h3 className="card-title">{announcement.title}</h3>
                  <span className="date-badge">{persianDate.toPersian(announcement.date)}</span>
                </div>
                <p className="card-description">{announcement.description}</p>
                <div className="card-details">
                  <div className="detail-item">
                    <span className="detail-label">زمان:</span>
                    <span className="detail-value">{announcement.time}</span>
                  </div>
                  <div className="detail-item">
                    <span className="detail-label">مکان:</span>
                    <span className="detail-value">{announcement.venue}</span>
                  </div>
                </div>
                <div className="card-actions">
                  <Link to={`/poster/${announcement.id}`} className="btn btn-outline">
                    <FaDownload />
                    مشاهده پوستر
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Empty State */}
      {announcements.length === 0 && (
        <section className="empty-section">
          <div className="empty-content">
            <FaTheaterMasks className="empty-icon" />
      <h3>هنوز آفیشی ثبت نشده</h3>
      <p>اولین آفیش خود را ایجاد کنید و برنامه‌های خود را مدیریت کنید.</p>
            <Link to="/dashboard" className="btn btn-primary">
              شروع کنید
            </Link>
          </div>
        </section>
      )}
    </div>
  );
};

export default Home;
